# ---------------------------------------------------------------- DOI 规范化
#
# 🔴 这一层就是上一轮 16 条 mismatch 里 12 条假阳性的来源，必须显式处理：
#   · 尾部粘控制字符：`10.1073/pnas.2200000001\b`（3 例，PDF 文字层把退格符带进来了）
#   · 尾部粘闭合符：`10.1016/j.ijhydene.2024.01.100⟩`
#   · 截断：`10.1088/2632-`、`10.1149/1945-7111/`
#   · 预印本 vs 正式版：`10.21203/rs.3.rs-…` vs `10.1038/s41467-…`
#
# 凡是「用正则做判定」的地方都要能对已知答案反算：下面每个分支在 --selftest 里
# 都有正例与反例（见 selftest()）。

# DOI 体：允许括号（Wiley SICI 等合法含括号），但**不允许**空白、引号、尖括号、
# Unicode 括号/引号/控制字符——这些是文字层拼接产物，不是 DOI 的一部分。
_DOI_BODY_STOP = (
    "\\s\"'<>"
    "\u27e8\u27e9\u3008\u3009\u300a\u300b\u300c\u300d\u300e\u300f"
    "\u2018\u2019\u201c\u201d\u00ab\u00bb"
    "\u3001\u3002\uff0c\uff1b\uff1a\uff01\uff1f"
    "\x00-\x1f\x7f-\x9f\u200b-\u200f\ufeff"
)
DOI_RE = re.compile(r"10\.\d{4,9}/[^" + _DOI_BODY_STOP + r"]+")

# 尾随脏字符：句读 + 闭合符（括号要按配对判断，见 _strip_tail）
_TAIL_PUNCT = ".,;:'\"\u2019\u201d\u27e9\u300b\u300d\u300f\u3001\u3002\uff0c\uff1b\uff1a"
_PAIRS = {")": "(", "]": "[", "}": "{"}

# 预印本注册号前缀（Research Square / bioRxiv / arXiv / SSRN / TechRxiv / ChemRxiv）
PREPRINT_PREFIXES = (
    "10.21203/", "10.1101/", "10.48550/", "10.2139/",
    "10.36227/", "10.26434/",
)

_DOI_PREFIXES = ("https://doi.org/", "http://doi.org/", "https://dx.doi.org/",
                 "http://dx.doi.org/", "doi.org/", "dx.doi.org/", "doi:", "doi ")
_VERSION_RE = re.compile(r"/v\d+$")
_URL_END = re.compile(r"[\s)\]}>\"',;]+$")

# 标题词覆盖用的英文虚词（不参与覆盖判定，否则「of/for/the」会把覆盖度抬到 1.0）
_TITLE_STOP = frozenset(
    "with from that this using into over than their these those based toward towards "
    "between under about which what when where while would could should upon via per "
    "large language model models study studies their its and for the of in on to a an "
    "by as at is are was were be been we our can may also such more most new".split())


def _strip_tail(doi):
    """去掉尾随句读与**多余的**闭合括号（成对括号不拆：`(SICI)…-3` 这类合法 DOI 保留）。"""
    while doi:
        ch = doi[-1]
        if ch in _TAIL_PUNCT:
            doi = doi[:-1]
            continue
        if ch in _PAIRS:
            opener = _PAIRS[ch]
            if doi.count(opener) < doi.count(ch):
                doi = doi[:-1]
                continue
        break
    return doi


def norm_doi(raw):
    """规范化 DOI 以便比较：去 URL/`doi:` 前缀、去控制字符与尾随脏字符、小写。

    返回 (doi, flags)。flags 是集合，可能含：
      "truncated"  —— 尾部停在 `-` / `/`，说明抽取被截断（不是另一个 DOI）
      "was_dirty"  —— 规范化前含控制字符/尾随闭合符（即上一轮那批假阳性）
    """
    if not raw:
        return "", set()
    s = str(raw)
    # 先砍控制字符（`\b` 等）与零宽字符：它们常被文字层插进 DOI 中间/尾部
    dirty = bool(re.search(r"[\x00-\x1f\x7f-\x9f\u200b-\u200f\ufeff]", s))
    s = re.sub(r"[\x00-\x1f\x7f-\x9f\u200b-\u200f\ufeff]", "", s)
    s = s.strip()
    low = s.lower()
    for p in _DOI_PREFIXES:
        if low.startswith(p):
            s = s[len(p):]
            break
    s = s.strip().strip("\"'")
    tail_before = s
    for p in _TAIL_PUNCT:                    # `https://doi.org/10.x⟩` 这类
        if s.endswith(p):
            s = s.rstrip(p)
    if s != tail_before:
        dirty = True                         # 尾随闭合符/句读也是「脏」的一种
    before_tail = s
    s = _strip_tail(s)
    if s != before_tail:
        dirty = True
    flags = set()
    if dirty:
        flags.add("was_dirty")
    if s.endswith("-") or s.endswith("/"):
        flags.add("truncated")
    return s.lower(), flags


# 上一轮一次性脚本的朴素判法（`\S+` 抓取 + rstrip('.,;') 直接字符串比较）。
# 这里保留一份**独立实现**，只用于报告「本工具归一化掉多少假阳性」——
# 判据纪律：新工具与旧实现在同一批数据上对总数，差出来的每一条都要能归类
# （历史事故：计数器与业务不是同一把尺）。
NAIVE_RE = re.compile(r"\b10\.\d{4,9}/[^\s\"'<>()\[\]]+", re.I)


def naive_doi(text):
    """旧实现：取频次最高者（并列取更长），只 rstrip 句读。→ 小写 DOI。"""
    cands = [c.rstrip(".,;") for c in NAIVE_RE.findall(text or "")]
    if not cands:
        return ""
    best, bestn = "", 0
    for c in cands:
        n = cands.count(c)
        if n > bestn or (n == bestn and len(c) > len(best)):
            best, bestn = c, n
    return best.lower()


def doi_key(doi):
    """比较键：去 `/v1` 版本后缀（Research Square 的预印本 DOI 带版本号）。"""
    return _VERSION_RE.sub("", doi)


def is_preprint(doi):
    return any(doi.startswith(p) for p in PREPRINT_PREFIXES)


def title_tokens(text):
    toks = re.findall(r"[a-z0-9][a-z0-9\-]{2,}", (text or "").lower())
    return [t for t in toks if len(t) >= 4 and t not in _TITLE_STOP]


def _same_tokens(card_title, pdf_text):
    """标题词覆盖度：卡片标题里 ≥4 字母的实词，有多少出现在 PDF 前几页文字里。"""
    toks = title_tokens(card_title)
    if len(toks) < 3:
        return 0.0
    low = (pdf_text or "").lower()
    hit = sum(1 for t in toks if t in low)
    return hit / float(len(toks))


def author_overlap(card_authors, pdf_text):
    """卡片作者名单在 PDF 前几页文字里的命中 → (比例, 命中数)。

    取每个作者的**最后一个词**作姓（"Carla C. D. Gamma" → gamma）。
    这一段是**证据**而不是装饰：预印本改名后唯一稳定的同篇判据就是作者名单。
    """
    if isinstance(card_authors, str):
        card_authors = [card_authors]
    surnames = []
    for a in card_authors or []:
        toks = re.findall(r"[A-Za-zÀ-ÿ'\-]+", str(a))
        if toks:
            surnames.append(toks[-1].lower())
    if not surnames:
        return 0.0, 0
    low = (pdf_text or "").lower()
    hits = sum(1 for s in surnames if s and s in low)
    return hits / float(len(surnames)), hits


def _looks_like_preprint_version(cd, pd, title, authors, text, chars):
    """预印本↔正式版：只在「注册号 + 作者 + 标题」三重证据齐全时才认（防把异篇放过）。"""
    if is_preprint(pd) == is_preprint(cd):
        return False
    if chars < PREPRINT_MIN_CHARS:
        return False
    cov = _same_tokens(title, text)
    ratio, hits = author_overlap(authors, text)
    if hits >= PREPRINT_AUTHORS_MIN_HITS and ratio >= PREPRINT_AUTHORS_MIN_RATIO \
            and cov >= PREPRINT_TITLE_MIN:
        return True
    # 卡片没有 authors 字段：只能退回「标题几乎一致」这一条弱信号
    if not (authors or []) and cov >= PREPRINT_TITLE_ONLY_MIN:
        return True
    return False


# 预印本↔正式版判定的证据要求（2026-10-31 标定）：
# 标题**不能**单独作判据——预印本常被改名（实测一例：预印本与正式版
# 标题用词大半不同，标题词覆盖只有约 0.5），
# 而两篇不同论文也能有 0.75 的覆盖。
# 稳定的是**作者名单**：本库 6 例同篇预印本实测作者命中 6/6…12/12（≥50% 全中），
# 异篇对照 0/9。故要求「预印本注册号 + 作者重叠 ≥50%(≥2 人) + 标题覆盖 ≥0.3」三项同时成立；
# 卡片没有 authors 字段时才退回「标题几近相同（≥0.6）」这一条弱信号。
PREPRINT_TITLE_MIN = 0.30        # 与作者重叠联用时的标题最低覆盖
PREPRINT_TITLE_ONLY_MIN = 0.60   # 无作者字段时的标题覆盖下限
PREPRINT_AUTHORS_MIN_RATIO = 0.5
PREPRINT_AUTHORS_MIN_HITS = 2
# 至少要有这么多字符文字才敢用标题/作者判定（单页封面不足以确认同一篇）
PREPRINT_MIN_CHARS = 400


# ---------------------------------------------------------------- PDF 读 DOI
def _fitz():
    try:
        import fitz
        return fitz
    except Exception:                                        # noqa: BLE001
        return None


def _silence_mupdf():
    """关掉 MuPDF 的 stderr 噪声（坏 PDF 上会刷几千行 `object is not a stream`）。

    🔴 不能靠「重定向 stderr」：那会把真错误一起吞掉，还会掩盖本工具自身的告警。
    只关 MuPDF 自己的错误/警告打印；读不出来的 PDF 仍由 read_pdf_text 的 error 字段显式报告。
    """
    fitz = _fitz()
    for fn in ("mupdf_display_errors", "mupdf_display_warnings"):
        try:
            getattr(fitz.TOOLS, fn)(False)
        except Exception:                                    # noqa: BLE001
            pass


def read_pdf_text(path, max_pages=DEFAULT_MAX_PAGES):
    """读 PDF 前 max_pages 页文字 → {"text","pages","chars","error"}。只读。"""
    fitz = _fitz()
    if fitz is None:
        return {"text": "", "pages": 0, "chars": 0,
                "error": "PyMuPDF 不可用（未安装 fitz）"}
    try:
        doc = fitz.open(str(path))
    except Exception as e:                                   # noqa: BLE001
        return {"text": "", "pages": 0, "chars": 0,
                "error": "无法打开 PDF：%s: %s" % (type(e).__name__, e)}
    try:
        n = min(max_pages, doc.page_count)
        pages = [(doc[i].get_text() or "") for i in range(n)]
        page_count = doc.page_count
    except Exception as e:                                   # noqa: BLE001
        return {"text": "", "pages": 0, "chars": 0,
                "error": "读取文字层失败：%s: %s" % (type(e).__name__, e)}
    finally:
        try:
            doc.close()
        except Exception:                                    # noqa: BLE001
            pass
    text = "\n".join(pages)
    return {"text": text, "pages": n, "page_count": page_count,
            "chars": len(re.sub(r"\s+", "", text)), "error": ""}


def extract_dois(text):
    """从文字里抓 DOI 候选 → [(原始片段, 规范化DOI, flags)]，按出现顺序。"""
    out = []
    for m in DOI_RE.finditer(text or ""):
        raw = m.group(0)
        doi, flags = norm_doi(raw)
        if doi:
            out.append((raw, doi, flags))
    return out


def _evidence(text, raw, span=55):
    i = (text or "").find(raw)
    if i < 0:
        return re.sub(r"\s+", " ", raw)[:120]
    frag = (text or "")[max(0, i - span): i + len(raw) + span]
    return re.sub(r"\s+", " ", frag).strip()


def pdf_doi(path, max_pages=DEFAULT_MAX_PAGES):
    """读一个 PDF 前 N 页 → {doi, flags, evidence, text, chars, pages, error}。

    DOI 取**出现频次最高**的那个（正文页常多次印；参考文献里的 DOI 更分散），
    频次相同取更长者（同一篇的截断副本不应胜出）。
    """
    tx = read_pdf_text(path, max_pages)
    info = {"doi": "", "flags": set(), "evidence": "", "text": tx["text"],
            "chars": tx["chars"], "pages": tx["pages"], "error": tx["error"]}
    if tx["error"]:
        return info
    cands = extract_dois(tx["text"])
    if not cands:
        return info
    cnt = collections.Counter((doi, tuple(sorted(flags))) for _raw, doi, flags in cands)
    best_doi, best_flags = "", ()
    best_n, best_len = -1, -1
    for (doi, flags), n in cnt.items():
        if n > best_n or (n == best_n and len(doi) > best_len):
            best_doi, best_flags, best_n, best_len = doi, flags, n, len(doi)
    info["doi"] = best_doi
    info["flags"] = set(best_flags)
    for raw, doi, flags in cands:
        if doi == best_doi:
            info["evidence"] = _evidence(tx["text"], raw)
            break
    return info


# ---------------------------------------------------------------- 卡 → PDF
def load_ledger(root):
    """读提取台账 → {text_rel: [pdf_rel, ...]}（保持台账里的顺序，多值不合并）。"""
    path = os.path.join(root, *LEDGER_REL.split("/"))
    if not os.path.isfile(path):
        return {}
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception:                                        # noqa: BLE001
        return {}
    rev = {}
    for pdf_rel, rec in (data.get("pdf") or {}).items():
        t = (rec or {}).get("text") if isinstance(rec, dict) else None
        if not t:
            continue
        t = t.replace("\\", "/")
        p = pdf_rel.replace("\\", "/")
        if p not in rev.setdefault(t, []):
            rev[t].append(p)
    return rev


def _raw_pdf_stem_index(root):
    """{pdf stem: [pdf_rel, ...]}，只扫 `raw/pdf/`，排除 `si/`。"""
    idx = {}
    base = os.path.join(root, "raw", "pdf")
    if not os.path.isdir(base):
        return idx
    si_abs = os.path.join(root, *SI_PREFIX.rstrip("/").split("/"))
    for dirpath, dirs, files in os.walk(base):
        if dirpath == si_abs or dirpath.startswith(si_abs + os.sep):
            dirs[:] = []
            continue
        rel_dir = os.path.relpath(dirpath, root).replace("\\", "/")
        for fn in files:
            if not fn.lower().endswith(".pdf"):
                continue
            idx.setdefault(os.path.splitext(fn)[0], []).append(rel_dir + "/" + fn)
    for k in idx:
        idx[k].sort()
    return idx


def linked_targets(fm):
    """frontmatter `sources:` 里的全部 wikilink 目标（去 `[[ ]]` / 别名）。"""
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    out = []
    for s in srcs:
        out += re.findall(r"\[\[([^\]|]+)", str(s))
    return [t.strip().replace("\\", "/") for t in out]


def _exists(root, rel):
    return os.path.isfile(os.path.join(root, *[x for x in rel.split("/") if x]))


def resolve_assoc(root, fm, card_rel, ledger_rev, stem_index=None):
    """卡片的关联 PDF 集合 → [{"pdf": rel, "source": 标签}]（去重、保序）。

    source 标签用于报告里说清「错的是哪一条关联」，避免把所有问题都归到卡片本身：
      sources      —— frontmatter 直接回链的 PDF
      ledger       —— 提取台账 text→pdf 反查（可能多值）
      text_stem    —— raw/pdf 下与 raw/text 同 stem 的 PDF（本库命名约定）
      project_refs —— 工程卡 references/PDF/<卡 stem>.pdf

    🔴 为什么**直链存在时也要看台账**：卡片常同时回链 PDF 与 raw/text 两件载体，
    而台账记录了「这件正文是从哪个 PDF 提取的」。两者若指向不同论文，卡片的关联
    本身就是**自相矛盾**的，下游（SI 判定 / 参数抽取）按台账取用就会用错论文
    —— 2026-10-30 的 模型A（直链对、台账另指 模型A-衍生版）与「方法卡A」
    （直链对、台账另指 数据集A 与 某论文丙 两篇）就是这样被用错的。
    早先实现先 `return` 直链（=「直链优先、台账只在缺直链时兜底」），此两例永远看不见。
    """
    assoc = []

    def add(rel, src):
        if not rel:
            return
        rel = rel.replace("\\", "/")
        # 🔴 SI 不是主文：`raw/pdf/si/**` 里印的是**主文参考文献**的 DOI（有时是数据集 DOI），
        # 拿它当主文核身份必然假阳性——2026-11-02 实测 3 张卡（卡片甲 / 卡片乙 /
        # 卡片丙）因此被判 mismatch。文件头早已声明"排除 raw/pdf/si/"，此处落实。
        if rel.lower().startswith(SI_PREFIX.lower()):
            return
        if _exists(root, rel) and not any(a["pdf"] == rel for a in assoc):
            assoc.append({"pdf": rel, "source": src})

    targets = linked_targets(fm)
    # ① 直接回链的 PDF（含工程卡 references/PDF）
    for t in targets:
        if t.lower().endswith(".pdf"):
            add(t, "sources")
    # ② 台账反查（同一 text 的全部候选都算关联——见文件头对 last-wins 的说明）
    for t in targets:
        if t.startswith("raw/text/") and t.lower().endswith(".md"):
            for p in ledger_rev.get(t, []):
                add(p, "ledger")
    if assoc:
        return assoc
    # ③ 同 stem 兜底（台账缺条目但命名约定成立）
    if stem_index is None:
        stem_index = _raw_pdf_stem_index(root)
    for t in targets:
        if t.startswith("raw/text/") and t.lower().endswith(".md"):
            stem = os.path.splitext(os.path.basename(t))[0]
            for p in stem_index.get(stem, []):
                add(p, "text_stem")
    if assoc:
        return assoc
    # ④ 工程卡：references/PDF/<卡 stem>.pdf
    parts = card_rel.split("/")
    if len(parts) >= 2 and parts[0] == "projects":
        stem = os.path.splitext(os.path.basename(card_rel))[0]
        add("%s/%s/%s/%s.pdf" % (parts[0], parts[1],
                                 PROJECT_REF_PDF.replace("\\", "/"), stem),
            "project_refs")
    return assoc


def card_title(body, card_rel):
    """卡片标题：正文首个 `# 标题`，缺失时退回卡名（去日期前缀与期刊后缀）。"""
    m = re.search(r"^#\s+(.+?)\s*$", body or "", re.M)
    if m:
        return m.group(1)
    stem = os.path.splitext(os.path.basename(card_rel))[0]
    stem = re.sub(r"^\d{4}[-_]", "", stem)
    return stem.replace("-", " ")


def classify(card_doi, assoc_info, title, authors=None, preprint_doi=None):
    """判定 → (verdict, chosen_info, why, matched, others)。

    assoc_info: [{"pdf","source","doi","flags","evidence","text","chars"}]
    判定顺序（🔴 顺序本身是判据，改动等于改结论）：
      卡片无 DOI → card_no_doi
      有「另一篇」→ mismatch（即使集合里也有同篇——那是关联冲突，同样会让下游用错论文）
      有同篇 → match
      预印本↔正式版 → preprint
      截断 DOI → doi_partial
      全都没 DOI → pdf_no_doi

    `preprint_doi` 是卡片 frontmatter 的显式声明：当 PDF 的 DOI 正好等于它，
    直接判 preprint，不再依赖「英文标题词覆盖 + 作者重叠」。中文标题卡的中文 H1
    不含英文实词，旧启发式必然失败（实测：某中文标题卡被误判 mismatch）。
    """
    cd_raw = (card_doi or "").strip()
    cd, cflags = norm_doi(cd_raw)
    if not cd:
        return "card_no_doi", None, "卡片 frontmatter 无 doi:", [], []
    cd_key = doi_key(cd)
    declared = set()
    for d in ([preprint_doi] if isinstance(preprint_doi, str) else (preprint_doi or [])):
        nd, _ = norm_doi(str(d))
        if nd:
            declared.add(doi_key(nd))
    declared_hit = False
    matched, partials, preprints, others, nodoi = [], [], [], [], []
    for info in assoc_info:
        pd = info.get("doi") or ""
        if not pd:
            nodoi.append(info)
            continue
        pd_key = doi_key(pd)
        if pd_key == cd_key:
            matched.append(info)
        elif cd_key.startswith(pd_key) or pd_key.startswith(cd_key):
            partials.append(info)
        elif is_preprint(pd) and pd_key in declared:
            preprints.append(info)
            declared_hit = True
        elif _looks_like_preprint_version(cd, pd, title, authors,
                                          info.get("text"), info.get("chars", 0)):
            preprints.append(info)
        else:
            others.append(info)
    srcs = "、".join(sorted({i["source"] for i in others})) if others else ""
    if others:
        if matched:
            why = ("关联冲突：卡片同篇 PDF 与另一篇 PDF 并存（另一篇来自 %s）——"
                   "台账/回链若按另一条取用，下游会指到错论文" % srcs)
        elif preprints:
            why = ("关联冲突：既有同篇预印本又有另一篇论文（另一篇来自 %s）" % srcs)
        else:
            why = "关联 PDF 的 DOI 属另一篇论文（来源：%s）" % srcs
        return "mismatch", others[0], why, matched, others
    if matched:
        why = "DOI 一致（含大小写/前缀/尾随脏字符归一化）"
        if preprints:
            why += "；集合内另有同篇预印本"
        return "match", matched[0], why, matched, others
    if preprints:
        why = ("卡片 preprint_doi 声明与 PDF 的 DOI 一致 ⇒ 同一篇的预印本"
               if declared_hit else
               "预印本注册号 + 作者重叠 + 标题覆盖三项吻合 ⇒ 同一篇的不同版本")
        return "preprint", preprints[0], why, matched, others
    if partials:
        return "doi_partial", partials[0], "PDF 内 DOI 是卡 DOI 的截断（抽取不全）", matched, others
    if nodoi:
        return "pdf_no_doi", nodoi[0], "PDF 前 N 页文字层没有 DOI", matched, others
    return "pdf_no_doi", None, "无可判定 PDF", matched, others


# ---------------------------------------------------------------- 扫描
def iter_cards(root, only=None):
    """要核对的卡：`wiki/sources/*.md` + `projects/<slug>/sources/*.md`（跳过 index.md）。

    口径与上一轮一致（当时只有 某工程 一个工程有文献卡）。工程卡的文件名里**没有**
    `raw/`，其 PDF 在 `projects/<slug>/references/PDF/`，由 resolve_assoc 的第 ④ 步接。
    """
    dirs = [os.path.join(root, "wiki", "sources")]
    pj = os.path.join(root, "projects")
    if os.path.isdir(pj):
        for slug in sorted(os.listdir(pj)):
            d = os.path.join(pj, slug, "sources")
            if os.path.isdir(d):
                dirs.append(d)
    for d in dirs:
        if not os.path.isdir(d):
            continue
        for fn in sorted(os.listdir(d)):
            if not fn.endswith(".md") or fn == "index.md":
                continue
            full = os.path.join(d, fn)
            rel = os.path.relpath(full, root).replace("\\", "/")
            if only:
                stem = os.path.splitext(fn)[0]
                if not (fnmatch.fnmatch(rel, only) or fnmatch.fnmatch(fn, only)
                        or fnmatch.fnmatch(stem, only)):
                    continue
            yield full, rel


def scan(root=None, only=None, limit=None, max_pages=DEFAULT_MAX_PAGES):
    """全量核对 → {"meta","counts","naive_baseline","rows"}。纯读。"""
    root = os.path.abspath(root or VAULT)
    t0 = time.time()
    ledger = load_ledger(root)
    stem_index = _raw_pdf_stem_index(root)
    pdf_cache = {}
    rows, skipped_no_pdf = [], 0
    cards = list(iter_cards(root, only))
    if limit is not None:
        cards = cards[:max(0, limit)]
    for full, rel in cards:
        fm_raw, body = K.split_frontmatter(K.read_text(full))
        fm = K.parse_frontmatter(fm_raw)
        doi_card_raw = str(fm.get("doi") or fm.get("source_doi") or "").strip()
        assoc = resolve_assoc(root, fm, rel, ledger, stem_index)
        if not assoc:
            skipped_no_pdf += 1        # 没有主文 PDF 的卡不在本工具的判定范围（同上一轮）
            continue
        infos = []
        for a in assoc:
            p = a["pdf"]
            if p not in pdf_cache:
                pdf_cache[p] = pdf_doi(os.path.join(root, *[x for x in p.split("/") if x]),
                                       max_pages)
            info = dict(pdf_cache[p])
            info.update({"pdf": p, "source": a["source"]})
            infos.append(info)
        verdict, chosen, why, matched, others = classify(
            doi_card_raw, infos, card_title(body, rel), fm.get("authors"),
            fm.get("preprint_doi"))
        # 旧朴素判法在同一份文字上的结论（只用于统计「归一化掉多少假阳性」）
        nv = ""
        if chosen:
            nv = naive_doi(chosen.get("text"))
        cd = norm_doi(doi_card_raw)[0] if doi_card_raw else ""
        if not cd:
            naive_verdict = "card_no_doi"
        elif not nv:
            naive_verdict = "pdf_no_doi"
        elif nv == cd:
            naive_verdict = "match"
        else:
            naive_verdict = "mismatch"
        row = {
            "card": rel,
            "doi_card": norm_doi(doi_card_raw)[0] if doi_card_raw else "",
            "doi_card_raw": doi_card_raw,
            "doi_pdf": chosen["doi"] if chosen else "",
            "verdict": verdict,
            # 冲突的子类：人工处置方式不同（清台账 vs 换 PDF），见技能文档
            "group": ("conflict_with_same_paper" if (verdict == "mismatch" and matched)
                      else "no_same_paper" if verdict == "mismatch" else ""),
            "pdf": chosen["pdf"] if chosen else assoc[0]["pdf"],
            "pdf_source": chosen["source"] if chosen else assoc[0]["source"],
            "evidence": chosen["evidence"] if chosen else "",
            "why": why,
            "naive_doi": nv,
            "naive_verdict": naive_verdict,
            "assoc": [{"pdf": i["pdf"], "source": i["source"], "doi": i["doi"],
                       "error": i.get("error") or ""} for i in infos],
        }
        rows.append(row)
    counts = collections.Counter(r["verdict"] for r in rows)
    # 与旧朴素判法对总数：旧法把多少条判成 mismatch，其中多少是判据噪声（本工具归一的）。
    # 🔴 判据纪律：新工具报出的每条差异都要能归到一类，归不了类的记 other 并逐条可见
    # （不许出现「剩下的解释不清」）。
    na = collections.OrderedDict(
        [("dirty_chars", 0), ("truncated", 0), ("preprint", 0),
         ("prefix_or_case", 0), ("other", 0)])
    naive_mis = [r for r in rows if r["naive_verdict"] == "mismatch"]
    for r in naive_mis:
        if r["verdict"] == "mismatch":
            continue
        if r["verdict"] == "preprint":
            na["preprint"] += 1
        elif r["verdict"] == "doi_partial":
            na["truncated"] += 1
        elif r["verdict"] == "match":
            _nd, nflags = norm_doi(r["naive_doi"])
            if "was_dirty" in nflags:
                na["dirty_chars"] += 1
            elif "truncated" in nflags:
                na["truncated"] += 1
            else:
                na["prefix_or_case"] += 1
        else:
            na["other"] += 1
    return {
        "meta": {
            "root": root,
            "scope": ["wiki/sources/*.md", "projects/*/sources/*.md"],
            "exclude": SI_PREFIX,
            "max_pages": max_pages,
            "cards_seen": len(cards),
            "cards_checked": len(rows),
            "cards_skipped_no_pdf": skipped_no_pdf,
            "unique_pdfs": len(pdf_cache),
            "elapsed_s": round(time.time() - t0, 1),
            "note": ("counts 与 rows 同一实现：cards_checked = len(rows) = 各 verdict 之和；"
                     "cards_skipped_no_pdf 不计入任何 verdict"),
        },
        "counts": dict(counts),
        "naive_baseline": {
            "rule": ("旧一次性脚本的判法：r'\\b10\\.\\d{4,9}/[^\\s\"\\'<>()\\[\\]]+' "
                     "取频次最高者 → rstrip('.,;') → 与卡片 doi 小写直接比较"),
            "naive_mismatch": len(naive_mis),
            "normalized_away": dict(na),
            "remaining_mismatch": len([r for r in rows if r["verdict"] == "mismatch"]),
            "note": ("naive_mismatch = remaining_mismatch + normalized_away 各项之和；"
                     "normalized_away 是判据噪声（脏字符/截断/预印本），不是真的关联错误"),
        },
        "rows": rows,
    }


def print_report(res, verbose=False):
    meta = res["meta"]
    counts = res["counts"]
    rows = res["rows"]
    order = ("match", "mismatch", "doi_partial", "preprint", "pdf_no_doi", "card_no_doi")
    print("=== 卡片 DOI ↔ 主文 PDF 同一篇核对（只读）===")
    print("库根: %s" % meta["root"])
    print("范围: %s   排除: %s   每篇读前 %d 页" % (
        " + ".join(meta["scope"]), meta["exclude"], meta["max_pages"]))
    print("卡: 见 %d / 核对 %d / 无主文 PDF 跳过 %d | 唯一 PDF %d | 用时 %ss" % (
        meta["cards_seen"], meta["cards_checked"], meta["cards_skipped_no_pdf"],
        meta["unique_pdfs"], meta["elapsed_s"]))
    print()
    print("判定计数（口径 = 已核对卡，各项之和 = %d）:" % meta["cards_checked"])
    for v in order + tuple(sorted(set(counts) - set(order))):
        if counts.get(v):
            print("  %-12s %4d" % (v, counts[v]))
    print()
    nb = res["naive_baseline"]
    naway = nb["normalized_away"]
    print("与旧朴素判法对总数（口径：同一批已核对卡、同一份 PDF 文字）:")
    print("  旧法判 mismatch %d 条 = 本工具判 mismatch %d 条 + 判据噪声 %d 条"
          % (nb["naive_mismatch"], nb["remaining_mismatch"],
             nb["naive_mismatch"] - nb["remaining_mismatch"]))
    print("  噪声分类: 尾部控制字符/闭合符 %d | 截断 DOI %d | 预印本↔正式版 %d |"
          " 前缀/大小写 %d | 其他 %d"
          % (naway["dirty_chars"], naway["truncated"], naway["preprint"],
             naway["prefix_or_case"], naway["other"]))
    print()
    bad = [r for r in rows if r["verdict"] == "mismatch"]
    n_conf = sum(1 for r in bad if r.get("group") == "conflict_with_same_paper")
    print("mismatch = %d（逐条）| 其中「台账另指一篇、直链本身是对的」%d 条，"
          "「关联里根本没有同篇 PDF」%d 条:" % (len(bad), n_conf, len(bad) - n_conf))
    for r in bad:
        print("  ✗ %s" % r["card"])
        print("      类别   : %s" % ("关联冲突（清/改台账重复映射即可，回链不必动）"
                                    if r.get("group") == "conflict_with_same_paper"
                                    else "无同篇 PDF（换 PDF 或改回链）"))
        print("      卡 DOI : %s" % r["doi_card"])
        print("      PDF DOI: %s   ← %s" % (r["doi_pdf"], r["pdf"]))
        print("      来源   : %s   %s" % (r["pdf_source"], r["why"]))
        if r["evidence"]:
            print("      证据   : …%s…" % r["evidence"][:150])
        alt = [a for a in r["assoc"] if a["pdf"] != r["pdf"]]
        for a in alt:
            print("      另关联 : %s  (doi=%s, 来源=%s)" % (a["pdf"], a["doi"], a["source"]))
    if verbose:
        print()
        print("全部核对行:")
        for r in rows:
            print("  %-12s %s | card=%s pdf=%s" % (
                r["verdict"], r["card"], r["doi_card"] or "-", r["doi_pdf"] or "-"))
            if r["verdict"] != "match":
                print("               %s" % r["why"])
    print()
    print("结论: %s" % ("干净——无真错配" if not bad
                      else "有 %d 条真错配，必须人工处理（见上文逐条）" % len(bad)))
    return len(bad)


# ---------------------------------------------------------------- 自检
def selftest():
    """已知答案反算：正例（该过的过）+ 反例（该报的报），临时夹具，不碰真实库。"""
    ok = fail = 0

    def chk(label, cond):
        nonlocal ok, fail
        if cond:
            ok += 1
            print("  [PASS] %s" % label)
        else:
            fail += 1
            print("  [FAIL] %s" % label)

    fitz = _fitz()
    if fitz is None:
        print("  [FAIL] PyMuPDF(fitz) 不可用，无法构造 PDF 夹具")
        print("SELFTEST FAILED: 0/1 cases correct")
        return 1

    # 🔴 用 kb_lib.make_temp_dir 而不是裸 tempfile.mkdtemp：本机受限环境下
    #    mkdtemp 产出的目录**可以建、往里建子目录却 Access Denied**
    #    （实测 WinError 5：目录建出来了 ≠ 能往里写）。
    d = K.make_temp_dir(prefix="qc_pdf_identity_")

    def mkpdf(rel, lines):
        p = os.path.join(d, *rel.split("/"))
        os.makedirs(os.path.dirname(p), exist_ok=True)
        doc = fitz.open()
        page = doc.new_page()
        y = 60
        for ln in lines:
            page.insert_text((45, y), ln, fontsize=9)
            y += 12
            if y > 780:
                page = doc.new_page()
                y = 60
        doc.save(p)
        doc.close()
        return rel

    def mkcard(rel, fm_lines, body="# Title\n"):
        p = os.path.join(d, *rel.split("/"))
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8", newline="") as f:
            f.write("---\n" + "\n".join(fm_lines) + "\n---\n" + body)
        return rel

    def mkledger(entries):
        p = os.path.join(d, *LEDGER_REL.split("/"))
        os.makedirs(os.path.dirname(p), exist_ok=True)
        payload = {"version": 2, "pdf": {}, "reconciled_at": "selftest"}
        for pdf_rel, text_rel in entries:
            payload["pdf"][pdf_rel] = {"text": text_rel, "status": "ok", "pages": 1}
        with open(p, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False)

    filler = ("We report a systematic study of the mechanical response of the "
              "candidate material under controlled conditions and benchmark every "
              "sample against the reference protocol described in the appendix. ")

    # ---- ① 归一化层：控制字符 / 闭合符 / 前缀 / 截断（纯函数，正例+反例）----
    print("— 归一化（正例：脏写法必须归一到同一 DOI）—")
    base = "10.1073/pnas.2200000001"
    chk("尾部控制字符 `\\b` 被去掉", norm_doi(base + "\x08")[0] == base)
    chk("尾部闭合符 `⟩` 被去掉", norm_doi(base + "\u27e9")[0] == base)
    chk("`https://doi.org/` 前缀被去掉",
        norm_doi("https://doi.org/" + base.upper())[0] == base)
    chk("`DOI:` 前缀 + 尾随句点被去掉", norm_doi("DOI: " + base + ".,;")[0] == base)
    chk("大写 DOI 归一化后小写", norm_doi(base.upper())[0] == base)
    chk("含成对括号的合法 DOI 不被拆坏",
        norm_doi("10.1002/(SICI)1099-1234(1998)01:1<55::AID>X")[0]
        == "10.1002/(sici)1099-1234(1998)01:1<55::aid>x")
    print("— 归一化（反例：不许把脏字符/截断当成同一个 DOI）—")
    chk("控制字符被标记 was_dirty", "was_dirty" in norm_doi(base + "\x08")[1])
    chk("尾部 `-` 被标记 truncated", "truncated" in norm_doi("10.1088/2632-")[1])
    chk("尾部 `/` 被标记 truncated", "truncated" in norm_doi("10.1149/1945-7111/")[1])
    chk("两个不同 DOI 归一化后仍不同",
        norm_doi("10.1021/acs.jcim.3c00001")[0] != norm_doi("10.1021/acs.jcim.6c00003")[0])
    chk("预印本判定：Research Square 是预印本", is_preprint("10.21203/rs.3.rs-7000001/v1"))
    chk("预印本判定：期刊 DOI 不是预印本", not is_preprint("10.1038/s41467-026-60002-z"))
    chk("版本后缀不影响比较键",
        doi_key("10.21203/rs.3.rs-7000001/v1") == doi_key("10.21203/rs.3.rs-7000001"))

    # ---- ② 端到端夹具（临时库根：卡 + PDF + 台账）----
    mkpdf("raw/pdf/01-x/Match Paper - J. Test - 2020.pdf",
          ["Match Paper", "https://doi.org/10.1234/abc.2020.001", "Journal of Tests 1 (2020)"])
    mkpdf("raw/pdf/01-x/Other Paper - J. Test - 2021.pdf",
          ["Other Paper", "DOI: 10.1234/other.2021.999", "Journal of Tests 2 (2021)"])
    mkpdf("raw/pdf/01-x/Truncated Paper - J. Test - 2022.pdf",
          ["Truncated Paper", "https://doi.org/10.1000/xyz-", "Journal of Tests 3 (2022)"])
    # 预印本夹具刻意**改过标题**（真实形态：预印本与正式版标题用词大半不同）。
    # 标题覆盖只有 0.5，唯一稳定的同篇判据是作者名单 ⇒ 夹具必须带作者。
    mkpdf("raw/pdf/01-x/Preprint Paper - J. Test - 2023.pdf",
          ["Sample Widget Failure At Example Interfaces: Removing The Sample Role",
           "Anna A. Alpha   Boris B. Beta",
           "https://doi.org/10.21203/rs.3.rs-1234567/v1", filler, filler, filler])
    mkpdf("raw/pdf/01-x/Preprint Different - J. Test - 2024.pdf",
          ["Totally Different Preprint", "https://doi.org/10.21203/rs.3.rs-9999999/v1",
           filler, filler, filler])
    mkpdf("raw/pdf/01-x/No Doi Paper - J. Test - 2025.pdf",
          ["No Doi Paper", "This scanned text layer carries no identifier at all.", filler])
    mkpdf("raw/pdf/01-x/Ledger A Paper - J. Test - 2026.pdf",
          ["Ledger A Paper", "https://doi.org/10.1234/ledger.a", filler])
    mkpdf("raw/pdf/01-x/Ledger B Paper - J. Test - 2026.pdf",
          ["Ledger B Paper", "https://doi.org/10.1234/ledger.b", filler])
    # SI 内页印的是**参考文献** DOI，不是主文 DOI（本库 3 张卡的真实形态）
    mkpdf("raw/pdf/si/SI Only Paper - J. Test - 2020.si.pdf",
          ["Supporting Information for Match Paper",
           "References: https://doi.org/10.1234/si.cited.ref", filler])
    mkpdf("raw/pdf/01-x/SI Main Paper - J. Test - 2020.pdf",
          ["Match Paper", "https://doi.org/10.1234/abc.2020.001", filler])
    mkpdf("projects/PX/references/PDF/2026-Project-Card-PX.pdf",
          ["Project Card Paper", "https://doi.org/10.1234/proj.001", filler])

    mkcard("wiki/sources/2020-match.md",
           ['type: source', 'doi: "10.1234/ABC.2020.001"',
            'sources:', '  - "[[raw/pdf/01-x/Match Paper - J. Test - 2020.pdf]]"',
            '  - "[[raw/text/01-x/Match Only Text.md]]"'],
           "# Match Paper\n")
    # 真错配：卡是 Match Paper，回链到 Other Paper 的 PDF
    mkcard("wiki/sources/2021-mismatch.md",
           ['type: source', 'doi: 10.1234/abc.2020.001',
            'sources:', '  - "[[raw/pdf/01-x/Other Paper - J. Test - 2021.pdf]]"'],
           "# Match Paper\n")
    mkcard("wiki/sources/2022-truncated.md",
           ['type: source', 'doi: 10.1000/xyz-123456',
            'sources:', '  - "[[raw/pdf/01-x/Truncated Paper - J. Test - 2022.pdf]]"'],
           "# Truncated Paper\n")
    mkcard("wiki/sources/2023-preprint.md",
           ['type: source', 'doi: "10.1038/s41467-026-000001-x"',
            'authors:', '  - Anna A. Alpha', '  - Boris B. Beta', '  - Carla C. Gamma',
            'sources:', '  - "[[raw/pdf/01-x/Preprint Paper - J. Test - 2023.pdf]]"'],
           "# Removal of sample interface widget failure in examples\n")
    mkcard("wiki/sources/2024-preprint-different.md",
           ['type: source', 'doi: "10.1038/s41467-026-000001-x"',
            'authors:', '  - Alice Smith', '  - Bob Jones',
            'sources:', '  - "[[raw/pdf/01-x/Preprint Different - J. Test - 2024.pdf]]"'],
           "# Removal of sample interface widget failure in examples\n")
    # 中文标题卡 + 显式 preprint_doi：卡片 H1 不含英文实词，旧启发式（标题覆盖）
    # 必然失败；此时只能靠 frontmatter 的显式声明认「同一篇的预印本」。
    mkcard("wiki/sources/2027-preprint-declared.md",
           ['type: source', 'doi: "10.1038/s41467-026-000001-x"',
            'preprint_doi: "10.21203/rs.3.rs-1234567/v1"',
            'sources:', '  - "[[raw/pdf/01-x/Preprint Paper - J. Test - 2023.pdf]]"'],
           "# 中文标题不含英文实词\n")
    mkcard("wiki/sources/2028-preprint-declared-wrong.md",
           ['type: source', 'doi: "10.1038/s41467-026-000001-x"',
            'preprint_doi: "10.21203/rs.3.rs-0000000/v1"',
            'sources:', '  - "[[raw/pdf/01-x/Preprint Paper - J. Test - 2023.pdf]]"'],
           "# 另一个中文标题\n")
    mkcard("wiki/sources/2025-no-doi.md",
           ['type: source', 'doi: 10.1234/abc.2020.001',
            'sources:', '  - "[[raw/pdf/01-x/No Doi Paper - J. Test - 2025.pdf]]"'],
           "# No Doi Paper\n")
    mkcard("wiki/sources/2026-card-no-doi.md",
           ['type: source',
            'sources:', '  - "[[raw/pdf/01-x/Match Paper - J. Test - 2020.pdf]]"'],
           "# Match Paper\n")
    # 台账一对多：同一 text 同时记在 A、B 两个 PDF 下（本库 7 组碰撞的真实形态）
    mkcard("wiki/sources/2026-ledger-collision.md",
           ['type: source', 'doi: 10.1234/ledger.a',
            'sources:', '  - "[[raw/text/01-x/Ledger Right Text.md]]"'],
           "# Ledger A Paper\n")
    # 直链正确 + 台账另记一篇（模型A / 方法卡A 的真实形态）
    mkcard("wiki/sources/2026-link-conflict.md",
           ['type: source', 'doi: 10.1234/abc.2020.001',
            'sources:', '  - "[[raw/pdf/01-x/Match Paper - J. Test - 2020.pdf]]"',
            '  - "[[raw/text/01-x/Link Conflict Text.md]]"'],
           "# Match Paper\n")
    # SI 回链不算主文：卡片同时有正文链与 SI 链，SI 里印着别篇的 DOI
    mkcard("wiki/sources/2027-si-only.md",
           ['type: source', 'doi: 10.1234/abc.2020.001',
            'sources:', '  - "[[raw/text/01-x/SI Only Text.md]]"',
            '  - "[[raw/pdf/si/SI Only Paper - J. Test - 2020.si.pdf]]"'],
           "# Match Paper\n")
    # 只回链 SI、没有主文 PDF ⇒ 无从核对，必须跳过而不是拿 SI 判 mismatch
    mkcard("wiki/sources/2027-si-no-main.md",
           ['type: source', 'doi: 10.1234/abc.2020.001',
            'sources:', '  - "[[raw/pdf/si/SI Only Paper - J. Test - 2020.si.pdf]]"'],
           "# Match Paper\n")
    mkcard("projects/PX/sources/2026-Project-Card-PX.md",
           ['type: source', 'doi: 10.1234/proj.001', 'source_type: Research Article',
            'sources:', '  - "[[references/Extract/2026-Project-Card-PX.md]]"'],
           "# Project Card Paper\n")
    mkledger([("raw/pdf/01-x/Ledger A Paper - J. Test - 2026.pdf",
               "raw/text/01-x/Ledger Right Text.md"),
              ("raw/pdf/01-x/Ledger B Paper - J. Test - 2026.pdf",
               "raw/text/01-x/Ledger Right Text.md"),
              ("raw/pdf/01-x/Match Paper - J. Test - 2020.pdf",
               "raw/text/01-x/Link Conflict Text.md"),
              ("raw/pdf/01-x/SI Main Paper - J. Test - 2020.pdf",
               "raw/text/01-x/SI Only Text.md"),
              ("raw/pdf/01-x/Other Paper - J. Test - 2021.pdf",
               "raw/text/01-x/Link Conflict Text.md")])

    print("— 预印本判据（单函数级：作者缺失时退回标题）—")
    _txt_hi = ("Removal of sample interface widget failure in examples "
               "in example systems under operating conditions. ") * 6
    _txt_lo = ("Completely unrelated content about robotics and cooking recipes. ") * 8
    chk("无 authors 时按标题近似认预印本",
        _looks_like_preprint_version("10.1038/x1", "10.21203/rs.3.rs-1/v1",
                                     "Removal of sample interface widget failure in examples",
                                     [], _txt_hi, 1200))
    chk("反例 有 authors 但 PDF 里一个都不出现 ⇒ 不认预印本（防放过异篇）",
        not _looks_like_preprint_version("10.1038/x1", "10.21203/rs.3.rs-1/v1",
                                         "Removal of sample interface widget failure in examples",
                                         ["Alice Smith", "Bob Jones"], _txt_hi, 1200))
    chk("反例 两边都是期刊 DOI（无预印本注册号）⇒ 不认预印本",
        not _looks_like_preprint_version("10.1038/x1", "10.1038/s41467-026-2-x",
                                         "Removal of sample interface widget failure in examples",
                                         [], _txt_hi, 1200))
    chk("反例 文字太少（扫描件）不敢用标题判定",
        not _looks_like_preprint_version("10.1038/x1", "10.21203/rs.3.rs-1/v1",
                                         "Removal of sample interface widget failure in examples",
                                         [], _txt_hi, 200))

    print("— 与旧朴素判法对总数（旧法必须多报，多报的必须能归类）—")
    _raw_dirty = "see DOI 10.1073/pnas.2200000001\x08 end"
    chk("旧朴素判法把尾部控制字符带进了 DOI（= 上一轮那批假阳性的来源）",
        naive_doi(_raw_dirty).endswith("\x08"))
    chk("按报告口径该条会被归入 dirty_chars（尚未归一化前字面不等）",
        naive_doi(_raw_dirty) != "10.1073/pnas.2200000001"
        and norm_doi(naive_doi(_raw_dirty))[0] == "10.1073/pnas.2200000001"
        and "was_dirty" in norm_doi(naive_doi(_raw_dirty))[1])
    chk("旧朴素判法不认预印本关系（同一篇的预印本会被判 mismatch）",
        naive_doi("DOI 10.21203/rs.3.rs-1234567/v1") != "10.1038/s41467-026-000001-x")

    print("— 端到端扫描（临时库根）—")
    res = scan(root=d, only="*.md")
    by = {os.path.basename(r["card"]): r for r in res["rows"]}

    def v(name):
        return by.get(name, {}).get("verdict")

    chk("正例 match：卡片 DOI 与 PDF DOI 一致（大小写/前缀已归一化）",
        v("2020-match.md") == "match")
    chk("正例 match 带证据片段",
        bool(by.get("2020-match.md", {}).get("evidence")))
    chk("正例 text 链在台账里没有条目时不误加关联（assoc 只有直链那 1 个）",
        len(by.get("2020-match.md", {}).get("assoc", [])) == 1)
    chk("反例 mismatch：回链到了另一篇论文的 PDF",
        v("2021-mismatch.md") == "mismatch")
    chk("反例 mismatch 打印出 PDF 侧 DOI 与来源",
        by.get("2021-mismatch.md", {}).get("doi_pdf") == "10.1234/other.2021.999"
        and by.get("2021-mismatch.md", {}).get("pdf_source") == "sources")
    chk("截断 DOI 判 doi_partial（不是 mismatch）", v("2022-truncated.md") == "doi_partial")
    chk("预印本↔正式版：标题被改名、作者吻合 ⇒ 判 preprint 而不是 mismatch",
        v("2023-preprint.md") == "preprint")
    chk("预印本判定的 why 写明依据（作者/标题）",
        "作者" in (by.get("2023-preprint.md", {}).get("why") or ""))
    chk("反例 同注册号但作者/标题都对不上 ⇒ mismatch（不放过异篇）",
        v("2024-preprint-different.md") == "mismatch")
    chk("中文标题卡 + preprint_doi 声明匹配 ⇒ preprint（不再误判 mismatch）",
        v("2027-preprint-declared.md") == "preprint")
    chk("声明依据写进 why",
        "preprint_doi" in (by.get("2027-preprint-declared.md", {}).get("why") or ""))
    chk("反例 preprint_doi 声明与 PDF 不符 ⇒ 仍 mismatch（声明不能凭空放过）",
        v("2028-preprint-declared-wrong.md") == "mismatch")
    chk("PDF 无 DOI 判 pdf_no_doi（不是 mismatch）", v("2025-no-doi.md") == "pdf_no_doi")
    chk("卡片无 DOI 判 card_no_doi", v("2026-card-no-doi.md") == "card_no_doi")
    chk("台账一对多：集合里混进另一篇 ⇒ mismatch（不因有同篇候选就放过）",
        v("2026-ledger-collision.md") == "mismatch")
    chk("台账一对多：两篇 PDF 都进 assoc，便于人工判断",
        len(by.get("2026-ledger-collision.md", {}).get("assoc", [])) == 2)
    chk("直链正确 + 台账另记一篇 ⇒ 仍判 mismatch（模型A/方法卡A 的形态）",
        v("2026-link-conflict.md") == "mismatch")
    chk("直链正确 + 台账冲突：挑出的是台账那篇并标 source=ledger",
        by.get("2026-link-conflict.md", {}).get("pdf_source") == "ledger")
    chk("SI 回链不参与主文身份核对（SI 内页 DOI 不得当主文 DOI）",
        v("2027-si-only.md") == "match"
        and all("/si/" not in a["pdf"] for a in by.get("2027-si-only.md", {}).get("assoc", [])))
    chk("只回链 SI、无主文 PDF ⇒ 跳过（不是 mismatch）",
        v("2027-si-no-main.md") is None)
    chk("计数与行一致（cards_checked = 各 verdict 之和）",
        res["meta"]["cards_checked"] == len(res["rows"])
        == sum(res["counts"].values()))
    chk("mismatch 计数与逐条行数一致",
        res["counts"].get("mismatch", 0)
        == len([r for r in res["rows"] if r["verdict"] == "mismatch"]))
    _nb = res["naive_baseline"]
    chk("与旧朴素判法对总数：naive_mismatch = 剩余 mismatch + 噪声各项之和（不许有解释不清的差）",
        _nb["naive_mismatch"] == _nb["remaining_mismatch"]
        + sum(_nb["normalized_away"].values()))
    # 工程卡：sources 只给 references/Extract，PDF 在 references/PDF/<卡 stem>.pdf
    res_pj = scan(root=d, only="2026-Project-Card-PX.md")
    chk("工程卡按 references/PDF/<卡 stem> 解析到主文 PDF 并判 match",
        len(res_pj["rows"]) == 1 and res_pj["rows"][0]["verdict"] == "match"
        and res_pj["rows"][0]["pdf_source"] == "project_refs")
    chk("--only 过滤生效（只跑指定卡）",
        res_pj["meta"]["cards_seen"] == 1)
    res_lim = scan(root=d, limit=1)
    chk("--limit 生效", res_lim["meta"]["cards_checked"] + res_lim["meta"]["cards_skipped_no_pdf"] == 1)

    K.remove_temp_dir(d)
    print()
    print("SELFTEST %s: %d/%d cases correct"
          % ("PASSED" if fail == 0 else "FAILED", ok, ok + fail))
    return 0 if fail == 0 else 1


# ---------------------------------------------------------------- CLI
def main(argv=None):
    K.console_encoding()
    _silence_mupdf()
    ap = argparse.ArgumentParser(
        prog="qc_pdf_identity.py",
        description="文献卡 doi: ↔ 主文 PDF 内页 DOI 同一篇核对（只读，不写盘）",
        epilog=("verdict: match / mismatch / doi_partial / preprint / pdf_no_doi / "
                "card_no_doi。mismatch 必须人工处理：把卡片 sources 回链改成同一篇的 PDF，"
                "或换掉那份 PDF（见 .dsh/skills/lit-pipeline/SKILL.md）。"),
    )
    ap.add_argument("--json", action="store_true", help="输出机器可读 JSON（行 + 计数）")
    ap.add_argument("--limit", type=int, default=None, help="只核对前 N 张卡")
    ap.add_argument("--only", default="", metavar="GLOB",
                    help="按 glob 过滤卡片路径/文件名，如 --only \"*模型A*\"")
    ap.add_argument("--verbose", action="store_true", help="逐行列出全部 verdict")
    ap.add_argument("--max-pages", type=int, default=DEFAULT_MAX_PAGES,
                    help="每篇 PDF 读前几页找 DOI（默认 %d）" % DEFAULT_MAX_PAGES)
    ap.add_argument("--selftest", action="store_true", help="自检（临时夹具，正例+反例）")
    args = ap.parse_args(argv)

    if args.selftest:
        return selftest()
    res = scan(only=args.only or None, limit=args.limit, max_pages=args.max_pages)
    if args.json:
        print(json.dumps(res, ensure_ascii=False, indent=1))
    else:
        print_report(res, verbose=args.verbose)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

